function renderLessons(listEl, lessons) {
  const fragment = document.createDocumentFragment();
  for (const lesson of lessons) {
    const li = document.createElement("li");
    const link = document.createElement("a");
    link.href = `/lessons/${encodeURIComponent(lesson.id)}`;
    link.textContent = lesson.title;           // safe: never parsed as HTML.
    li.append(link);
    fragment.append(li);
  }
  listEl.replaceChildren(fragment);            // one update; old items removed.
}

renderLessons(document.querySelector("#lessons"), [
  { id: "loops", title: "Loops" },
  { id: "maps", title: "Maps <new>" },
]);
```

